229	    /**
230	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city} or
231	     * {@code telephone} is missing (null) or blank (empty or whitespace only). Bean Validation on
232	     * the request body already rejects null and empty values, but permits whitespace-only strings
233	     * for fields without a stricter pattern (e.g. {@code city}, {@code address}); this guard closes
234	     * that gap so every required field must carry a non-blank value.
235	     *
236	     * @param ownerFieldsDto the submitted owner fields
237	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
238	     */
239	    private void rejectBlankOwnerFields(OwnerFieldsDto ownerFieldsDto) {
240	        List<String> missing = new ArrayList<>();
241	        addIfBlank(missing, "firstName", ownerFieldsDto.getFirstName());
242	        addIfBlank(missing, "lastName", ownerFieldsDto.getLastName());
243	        addIfBlank(missing, "address", ownerFieldsDto.getAddress());
244	        addIfBlank(missing, "city", ownerFieldsDto.getCity());
245	        addIfBlank(missing, "telephone", ownerFieldsDto.getTelephone());
246	        if (!missing.isEmpty()) {
247	            throw new InvalidOwnerFieldsException(missing);
248	        }
249	    }
250	
251	    private void addIfBlank(List<String> missing, String fieldName, String value) {
252	        if (value == null || value.isBlank()) {
253	            missing.add(fieldName);
254	        }
255	    }
256	
257	    /**
258	     * Normalizes the submitted {@code telephone} on create to its canonical form (see
259	     * {@link TelephoneNormalizer#normalize}) and writes it back onto the request so it is the value
260	     * stored and returned. Any input that does not reduce to a valid telephone is rejected with a
261	     * {@code 400 Bad Request}.
262	     *
263	     * @param ownerFieldsDto the submitted owner fields (its {@code telephone} is non-blank here,
264	     *                       {@link #rejectBlankOwnerFields} having already run)
265	     * @throws InvalidOwnerFieldsException if the telephone cannot be normalized to a valid value
266	     */
267	    private void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
268	        String normalized = TelephoneNormalizer.normalize(ownerFieldsDto.getTelephone())
269	            .orElseThrow(() -> new InvalidOwnerFieldsException(List.of("telephone")));
270	        ownerFieldsDto.setTelephone(normalized);
271	    }
272	
273	    /**
274	     * Normalizes an optionally-supplied {@code email}. When absent (null) or blank the field is left
275	     * untouched (email is optional). When present it is trimmed and, after validating that it is a
276	     * syntactically valid address, written back lower-cased so it is the value stored and returned.
277	     * Any present-but-invalid address is rejected with a {@code 400 Bad Request}.
278	     *
279	     * @param ownerFieldsDto the submitted owner fields
280	     * @throws InvalidOwnerFieldsException if the email is present but not a syntactically valid address
281	     */
282	    private void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
283	        String email = ownerFieldsDto.getEmail();
284	        if (email == null || email.isBlank()) {
285	            return;
286	        }
287	        email = email.trim();
288	        if (!EMAIL_PATTERN.matcher(email).matches()) {
289	            throw new InvalidOwnerFieldsException(List.of("email"));
290	        }
291	        ownerFieldsDto.setEmail(email.toLowerCase(Locale.ROOT));
292	    }
293	
294	    /**
295	     * Rejects creating an owner whose normalized telephone is already used by any other owner.
296	     * Both the submitted telephone and every existing owner's stored telephone are reduced to their
297	     * {@linkplain TelephoneNormalizer#toComparisonKey comparison key} before comparison, so equality
298	     * is judged on that key alone. A match is reported as a {@code 409 Conflict}.
299	     *
300	     * @param normalizedTelephone the submitted telephone, already reduced to its canonical form by
301	     *                            {@link #normalizeTelephone}
302	     * @throws DuplicateOwnerTelephoneException if another owner already uses the same telephone
303	     */
304	    private void rejectDuplicateTelephone(String normalizedTelephone) {
305	        String comparisonKey = TelephoneNormalizer.toComparisonKey(normalizedTelephone);
306	        boolean inUse = this.clinicService.findAllOwners().stream()
307	            .map(Owner::getTelephone)
308	            .filter(Objects::nonNull)
309	            .map(TelephoneNormalizer::toComparisonKey)
310	            .anyMatch(comparisonKey::equals);
311	        if (inUse) {
312	            throw new DuplicateOwnerTelephoneException(normalizedTelephone);
313	        }
314	    }
315	}
